// frontend/src/components/MapView.js
import React, { useState, useEffect } from "react";
import API from "../api";
import PropTypes from "prop-types";
import { gpsToMapPercent } from "../utils/coordConverter";
import "./MapView.css";

/**
 * MapView
 * Frontend-only interactive campus map component.
 * - Uses a static image as the map background (no external map libs)
 * - Places markers using absolute positioning with x/y percentage coords
 * - Clicking a marker displays lab details in a modal
 * - Responsive and reusable
 * - Uses Tailwind classes; includes fallback CSS in MapView.css
 */
const MapView = ({
  imageUrl = `${process.env.PUBLIC_URL}/Campus map.png`,
  markers = [],
}) => {
  const [activeMarker, setActiveMarker] = useState(null);
  const [eventsByDate, setEventsByDate] = useState({});
  const [loadingEvents, setLoadingEvents] = useState(false);
  const [eventsError, setEventsError] = useState(null);

  // open marker and load events for that hall
  const openMarker = (m) => {
    setActiveMarker(m);
    setEventsByDate({});
    setEventsError(null);

    const hallId = m.hallId || m.id;
    if (!hallId) return;

    setLoadingEvents(true);
    API.get("/events", { params: { hallId } })
      .then((res) => {
        const grouped = {};
        (res.data || []).forEach((ev) => {
          const d = new Date(ev.date).toDateString();
          if (!grouped[d]) grouped[d] = [];
          grouped[d].push(ev);
        });
        setEventsByDate(grouped);
      })
      .catch((err) => {
        setEventsError("Failed to load events.");
      })
      .finally(() => setLoadingEvents(false));
  };

  // Close modal on ESC
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") setActiveMarker(null);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <div className="mapview-root px-4 py-6">
      <div className="mapview-wrapper max-w-6xl mx-auto">
        {/* Map area */}
        <div className="relative mapview-box">
          <img
            src={encodeURI(imageUrl)}
            alt="Campus map"
            className="mapview-image w-full h-auto block rounded-lg shadow"
            draggable={false}
          />

          {/* Overlay for markers */}
          <div className="absolute inset-0 pointer-events-none">
            {(markers || []).map((m) => (
              <button
                key={m.id}
                type="button"
                className="map-marker pointer-events-auto"
                style={{
                  left: `${m.x}%`,
                  top: `${m.y}%`,
                  transform: "translate(-50%, -100%)",
                }}
                onClick={() => openMarker(m)}
                title={m.title}
                aria-label={`Open details for ${m.title}`}
              >
                <span className="marker-dot">📍</span>
              </button>
            ))}
          </div>
        </div>

        {/* Modal */}
        {activeMarker && (
          <div
            className="map-modal fixed inset-0 z-50 flex items-center justify-center p-4"
            onClick={() => setActiveMarker(null)}
          >
            <div
              className="map-modal-card bg-white rounded-lg shadow-lg max-w-lg w-full p-6"
              onClick={(e) => e.stopPropagation()}
              role="dialog"
              aria-modal="true"
            >
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="text-xl font-semibold">
                    {activeMarker.title}
                  </h3>
                  {activeMarker.subtitle && (
                    <p className="text-sm text-gray-600">
                      {activeMarker.subtitle}
                    </p>
                  )}
                </div>
                <button
                  aria-label="Close"
                  className="text-gray-500 hover:text-gray-800"
                  onClick={() => setActiveMarker(null)}
                >
                  ✕
                </button>
              </div>

              {activeMarker.description && (
                <p className="mt-4 text-sm text-gray-700">
                  {activeMarker.description}
                </p>
              )}

              <div className="mt-4">
                <h4 className="font-semibold">Events</h4>
                {loadingEvents && <p className="text-sm">Loading events…</p>}
                {eventsError && (
                  <p className="text-sm text-red-600">{eventsError}</p>
                )}
                {!loadingEvents &&
                  !eventsError &&
                  Object.keys(eventsByDate).length === 0 && (
                    <p className="text-sm text-gray-600">
                      No upcoming events for this hall.
                    </p>
                  )}

                {!loadingEvents &&
                  Object.entries(eventsByDate).map(([date, events]) => (
                    <div key={date} className="mt-2">
                      <div className="text-sm font-medium">{date}</div>
                      <ul className="list-disc list-inside text-sm">
                        {events.map((ev) => (
                          <li key={ev._id || ev.id}>
                            {ev.title} ({ev.startTime || ev.time || "—"} -{" "}
                            {ev.endTime || "—"})
                          </li>
                        ))}
                      </ul>
                    </div>
                  ))}
              </div>

              <div className="mt-6 text-right">
                <button
                  className="btn-close bg-gray-100 px-3 py-1 rounded hover:bg-gray-200"
                  onClick={() => setActiveMarker(null)}
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

MapView.propTypes = {
  imageUrl: PropTypes.string,
  markers: PropTypes.arrayOf(
    PropTypes.shape({
      id: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
      x: PropTypes.number.isRequired,
      y: PropTypes.number.isRequired,
      title: PropTypes.string.isRequired,
      subtitle: PropTypes.string,
      description: PropTypes.string,
    }),
  ),
};

MapView.defaultProps = {
  markers: (() => {
    // Campus map GPS bounds (estimated from hall coordinates)
    const mapBounds = {
      minLat: 16.24765,
      maxLat: 16.24775,
      minLng: 80.43095,
      maxLng: 80.4314,
    };

    const halls = [
      {
        hallId: "newton-hall",
        name: "Newton Seminar Hall",
        lat: 16.24765111,
        lng: 80.4310964,
        description:
          "Newton Seminar Hall\n16.24765111, 80.4310964 | Alt: 33.17 m | Dir: 182.77°",
      },
      {
        hallId: "cv-raman-hall",
        name: "CV Raman Seminar Hall",
        lat: 16.24773746,
        lng: 80.43097479,
        description:
          "CV Raman Seminar Hall\n16.24773746, 80.43097479 | Alt: 33.05 m | Dir: 86.08°",
      },
      {
        hallId: "abdul-kalam-hall",
        name: "Abdul Kalam Seminar Hall",
        lat: 16.24772907,
        lng: 80.4313729,
        description:
          "Abdul Kalam Seminar Hall\n16.24772907, 80.4313729 | Alt: 33.45 m | Dir: 382.43°",
      },
    ];

    return halls.map((hall, idx) => {
      const { x, y } = gpsToMapPercent(hall.lat, hall.lng, mapBounds);
      return {
        id: `hall-${idx + 1}`,
        hallId: hall.hallId,
        x,
        y,
        title: hall.name,
        subtitle: "Seminar Hall",
        description: hall.description,
      };
    });
  })(),
  imageUrl: `${process.env.PUBLIC_URL}/Campus map.png`,
};

export default MapView;
